use serde_json::Value;

pub fn solve(input: Value) -> Value {
    match input {
        Value::Array(arr) => {
            let sum: i64 = arr.iter()
                .filter_map(|item| item.as_i64())
                .sum();
            Value::Number(serde_json::Number::from(sum))
        },
        _ => Value::Null,
    }
}
